<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class CashController extends Controller{
 private function expected(int$id):float{return app(\App\Services\CashService::class)->expected($id);}
 public function history(Request$r){$q=DB::table('cash_sessions as s')->leftJoin('users as u','u.id','=','s.user_id')->leftJoin('cash_registers as cr','cr.id','=','s.cash_register_id')->where(['s.company_id'=>$r->user()->company_id,'s.branch_id'=>$r->user()->branch_id])->select('s.*','u.name as user_name','cr.name as cash_register_name');if($r->status)$q->where('s.status',$r->status);return response()->json(['success'=>true,'data'=>$q->latest('s.opened_at')->limit(300)->get()]);}
 public function detail(Request$r,int$id){$s=DB::table('cash_sessions as cs')->leftJoin('users as u','u.id','=','cs.user_id')->leftJoin('cash_registers as cr','cr.id','=','cs.cash_register_id')->where(['cs.id'=>$id,'cs.company_id'=>$r->user()->company_id])->select('cs.*','u.name as user_name','cr.name as cash_register_name')->firstOrFail();$s->movements=DB::table('cash_movements')->where('cash_session_id',$id)->latest()->get();$s->audits=DB::table('cash_audits')->where('cash_session_id',$id)->latest()->get();$s->calculated_expected=$this->expected($id);return response()->json(['success'=>true,'data'=>$s]);}
 public function audit(Request$r){$c=$r->user()->company_id;$b=$r->user()->branch_id;$d=$r->validate(['counted_amount'=>'required|numeric|min:0','denominations'=>'nullable|array','notes'=>'nullable']);$q=DB::table('cash_sessions')->where(['company_id'=>$c,'branch_id'=>$b,'status'=>'open']);$r->user()->cash_session_id?$q->where('id',$r->user()->cash_session_id):$q->where('user_id',$r->user()->id);$s=$q->latest()->firstOrFail();$expected=$this->expected($s->id);$id=DB::table('cash_audits')->insertGetId(['cash_session_id'=>$s->id,'user_id'=>$r->user()->id,'type'=>'partial','expected_amount'=>$expected,'counted_amount'=>$d['counted_amount'],'difference'=>$d['counted_amount']-$expected,'denominations'=>isset($d['denominations'])?json_encode($d['denominations']):null,'notes'=>$d['notes']??null,'created_at'=>now(),'updated_at'=>now()]);return response()->json(['success'=>true,'message'=>'Arqueo parcial registrado','data'=>['id'=>$id,'expected'=>$expected,'difference'=>$d['counted_amount']-$expected]],201);}
 public function differences(Request$r){$c=$r->user()->company_id;return response()->json(['success'=>true,'data'=>DB::table('cash_audits as a')->join('cash_sessions as s','s.id','=','a.cash_session_id')->join('users as u','u.id','=','a.user_id')->where('s.company_id',$c)->select('a.*','s.opened_at','u.name as user_name')->latest('a.created_at')->limit(500)->get()]);}
}
